patches.diff:
From ac7d53a20d2df5cd6365d05c8cbd3f2699e67f53 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:54:09 +0100
Subject: [PATCH] startplasma: don't override keyboard settings the user
 already set

startplasma replaced the XKB_DEFAULT_* variables a user set, e.g. in
.profile, with localed's. Now if a layout or variant is set, localed's
layout, variant and options are all left out, so they don't get mixed.

BUG: 447203
---
 startkde/startplasma.cpp | 11 +++++++----
 1 file changed, 7 insertions(+), 4 deletions(-)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..18524b1292 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -830,15 +830,18 @@ int main(int argc, char **argv)

             auto queryAndSet = [&result](const char *var, const QString &value) {
                 const auto r = result.value(value).toString();
-                if (!r.isEmpty()) {
+                if (!r.isEmpty() && !qEnvironmentVariableIsSet(var)) {
                     qputenv(var, r.toUtf8());
                 }
             };

             queryAndSet("XKB_DEFAULT_MODEL", QStringLiteral("X11Model"));
-            queryAndSet("XKB_DEFAULT_LAYOUT", QStringLiteral("X11Layout"));
-            queryAndSet("XKB_DEFAULT_VARIANT", QStringLiteral("X11Variant"));
-            queryAndSet("XKB_DEFAULT_OPTIONS", QStringLiteral("X11Options"));
+            // The system's variants and options belong to its layouts, don't mix them with the user's
+            if (!qEnvironmentVariableIsSet("XKB_DEFAULT_LAYOUT") && !qEnvironmentVariableIsSet("XKB_DEFAULT_VARIANT")) {
+                queryAndSet("XKB_DEFAULT_LAYOUT", QStringLiteral("X11Layout"));
+                queryAndSet("XKB_DEFAULT_VARIANT", QStringLiteral("X11Variant"));
+                queryAndSet("XKB_DEFAULT_OPTIONS", QStringLiteral("X11Options"));
+            }
         } else {
             qCWarning(PLASMA_STARTUP) << "not a reply org.freedesktop.locale1" << resultMessage;
         }
-- 
